  "Heat ghee; splutter cumin, add ginger-chilli paste": ["घी गरम करें; जीरा चटकाएँ, अदरक-मिर्च पेस्ट डालें", "ঘি গরম করুন; জিরে ফোড়ন দিন, আদা-লঙ্কার পেস্ট দিন"],
  "Add tomato purée; cook until ghee separates": ["टमाटर प्यूरी डालें; घी अलग होने तक पकाएँ", "টমেটো পিউরি দিন; ঘি ছাড়া পর্যন্ত রাঁধুন"],
  "Add broken potatoes, sendha namak and 1½ cups water": ["टूटे आलू, सेंधा नमक और 1½ कप पानी डालें", "ভাঙা আলু, সৈন্ধব লবণ ও দেড় কাপ জল দিন"],
  "Simmer 10 min until the gravy thickens slightly": ["10 मिनट पकाएँ जब तक ग्रेवी थोड़ी गाढ़ी न हो जाए", "১০ মিনিট রাঁধুন যতক্ষণ না ঝোল সামান্য ঘন হয়"],
  "Finish with coriander; serve with kuttu or singhara puri": ["हरा धनिया डालें; कुट्टू या सिंघाड़े की पूरी के साथ परोसें", "ধনেপাতা দিন; কুট্টু বা পানিফলের পুরির সঙ্গে পরিবেশন করুন"],
  "Navratri / vrat": ["नवरात्रि / व्रत", "নবরাত্রি / ব্রত"],
  "Kuttu (buckwheat) flour": ["कुट्टू का आटा", "কুট্টুর আটা"],
  "Boiled potato (mashed)": ["उबला आलू (मसला हुआ)", "সেদ্ধ আলু (চটকানো)"],
  "Ghee/oil for frying": ["तलने के लिए घी/तेल", "ভাজার জন্য ঘি/তেল"],
  "Knead kuttu flour with mashed potato and sendha namak (little/no water)": ["कुट्टू आटे को मसले आलू और सेंधा नमक के साथ गूँधें (बहुत कम या बिना पानी)", "কুট্টুর আটা চটকানো আলু ও সৈন্ধব লবণ দিয়ে মাখুন (খুব কম বা জল ছাড়া)"],
  "Rest 10 minutes; make small balls": ["10 मिनट रखें; छोटी लोइयाँ बनाएँ", "১০ মিনিট রাখুন; ছোট লেচি কাটুন"],
  "Roll gently between greased sheets (kuttu dough is delicate)": ["घी लगी शीट के बीच हल्के हाथ से बेलें (कुट्टू का आटा नाज़ुक होता है)", "ঘি মাখানো শিটের মাঝে আলতো করে বেলুন (কুট্টুর আটা নরম)"],
  "Deep fry in medium-hot ghee until puffed and golden": ["मध्यम गरम घी में फूलने और सुनहरा होने तक तलें", "মাঝারি গরম ঘিতে ফুলে সোনালি হওয়া পর্যন্ত ভাজুন"],
  "Serve hot with vrat aloo-tamatar and dahi": ["व्रत वाले आलू-टमाटर और दही के साथ गरम परोसें", "ব্রতের আলু-টমেটো ও দইয়ের সঙ্গে গরম পরিবেশন করুন"],
  "Every abhishek & puja — the five nectars": ["हर अभिषेक और पूजा में: पाँच अमृत", "প্রতিটি অভিষেক ও পূজায়: পাঁচ অমৃত"],
